function parseTSV(data: string): Place[] {
  const lines = data.trim().split('\n');
  if (lines.length < 2) return [];

  const headers = lines[0].split('\t').map(h => {
    const trimmed = h.trim();
    return trimmed.charAt(0).toLowerCase() + trimmed.slice(1).replace(/ (\w)/g, (_, c) => c.toUpperCase());
  });

  const titleIndex = headers.indexOf('title');
  const addedIndex = headers.indexOf('added');

  if (titleIndex === -1 || addedIndex === -1) {
    console.error("TSV is missing 'Title' or 'Added' column");
    return [];
  }

  const places: Place[] = [];
  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split('\t').map(v => v.trim());
    
    const isAdded = values[addedIndex] === 'TRUE';
    if (!isAdded || !values[titleIndex]) continue;

    const place: any = {};
    headers.forEach((header, index) => {
      place[header] = values[index] || '';
    });
    places.push(place as Place);
  }
  return places;
}

export const FULL_STL_DATABASE: Place[] = parseTSV(tsvData);

export const STL_DATABASE_TITLES: string[] = FULL_STL_DATABASE.map(p => p.title);
